/**
 * Early event capture (ADR-016): a tiny inline script, placed before the bundle, records the events a
 * user makes before the application has hydrated. `hydrate()` then replays them once its handlers are
 * attached, so a click made while the page was still loading is not lost. The script is generated by
 * `generateHydrationScript` on the server; the replay is the client half, and it does nothing when the
 * page has no captured events.
 */

/** The event types recorded when a page does not name its own. @internal */
export const DEFAULT_EARLY_EVENTS: readonly string[] = ["click", "input"];

/** The window property the capture script writes. Its shape is checked before use. @internal */
export const EARLY_CAPTURE_KEY = "__SHADOWJS_EARLY__";

/**
 * The most events the capture script keeps. A page whose bundle never loads would otherwise hold every
 * click and keystroke of the visit; the first ones are the ones worth replaying. @internal
 */
export const MAX_EARLY_EVENTS = 100;

/** Event names are plain lower-case words: anything else would end up inside the script text. */
const EVENT_NAME = /^[a-z]+$/;

/**
 * The inline script body. A capture listener on the document (capture phase, so it sees events even
 * when a page stops their propagation) queues each event; the queue and the listener are kept on
 * `window` for the replay.
 * @internal
 */
export function captureScriptBody(names: readonly string[]): string {
  const list = JSON.stringify(names.filter((name) => EVENT_NAME.test(name)));
  return (
    "(function(){var d=document,n=" +
    list +
    `,q=[];function c(e){if(q.length<${MAX_EARLY_EVENTS})q.push(e)}` +
    "for(var i=0;i<n.length;i++)d.addEventListener(n[i],c,true);" +
    `window.${EARLY_CAPTURE_KEY}={queue:q,names:n,listener:c};})();`
  );
}

interface Capture {
  readonly queue: Event[];
  readonly names: string[];
  readonly listener: (event: Event) => void;
}

/** The capture the script left on the window, validated, or undefined. */
function readCapture(): Capture | undefined {
  const value: unknown = Reflect.get(globalThis, EARLY_CAPTURE_KEY);
  if (typeof value !== "object" || value === null) return undefined;
  const queue: unknown = Reflect.get(value, "queue");
  const names: unknown = Reflect.get(value, "names");
  const listener: unknown = Reflect.get(value, "listener");
  if (!Array.isArray(queue) || !Array.isArray(names) || typeof listener !== "function") {
    return undefined;
  }
  const events = queue.filter((item): item is Event => item instanceof Event);
  const kinds = names.filter((name): name is string => typeof name === "string");
  return { queue: events, names: kinds, listener: listener as (event: Event) => void };
}

/** A new event of the same type that bubbles like the original and carries its pointer position. */
function reissue(event: Event): Event {
  const init: EventInit = { bubbles: true, cancelable: event.cancelable, composed: true };
  if (event instanceof MouseEvent) {
    return new MouseEvent(event.type, {
      ...init,
      clientX: event.clientX,
      clientY: event.clientY,
      button: event.button,
      buttons: event.buttons,
      altKey: event.altKey,
      ctrlKey: event.ctrlKey,
      metaKey: event.metaKey,
      shiftKey: event.shiftKey,
    });
  }
  return new Event(event.type, init);
}

/**
 * Stops the capture and replays what it recorded, in order, on the elements they were made on. Called
 * by `hydrate()` after the handlers are attached. Does nothing when no capture ran.
 * @internal
 */
export function replayEarlyEvents(): void {
  const capture = readCapture();
  if (capture === undefined) return;
  Reflect.deleteProperty(globalThis, EARLY_CAPTURE_KEY);
  for (const name of capture.names) document.removeEventListener(name, capture.listener, true);
  for (const event of capture.queue) {
    const target = event.target;
    if (target instanceof Node) target.dispatchEvent(withoutDefaultAction(reissue(event)));
  }
}

/**
 * The replayed event runs the page's handlers, not the browser's default action: the real event
 * already ran it when the user made it. A dispatched `click` on a link follows the link, so without
 * this a link was followed twice. The native flag is set right away, which cancels the default action,
 * and the handlers still see `defaultPrevented` as false (a router skips a click that is already
 * prevented) until one of them prevents it itself.
 */
function withoutDefaultAction(event: Event): Event {
  event.preventDefault();
  let prevented = false;
  Object.defineProperties(event, {
    defaultPrevented: { get: () => prevented },
    preventDefault: {
      value: () => {
        prevented = true;
      },
    },
  });
  return event;
}
